122	     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)}) with
123	     * its tags, comma separated (see {@link Claim#tagsOf}). CLAIM_ADDED ends with tags=&lt;tags, sorted and
124	     * comma separated&gt; when any were given.
125	     */
126	    @Transactional
127	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
128	            String corrects, String ref, String tags) {
129	        Rollups.Rollup before = rollups.take(sheetId);
130	        Person person = person(sheetId, personId);
131	        LocalDate dated = date != null ? date : sheets.load(sheetId).defaultClaimDate();
132	        Sheet sheet = sheets.lock(sheetId);
133	        int terms = terms(sheet, person, dated);
134	        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
135	        refuseIfRetired(person, dated);
136	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
137	        String referred = reference(ref);
138	        refuseIfReferred(sheetId, referred, null);
139	        Claim added = new Claim(sheetId, personId, money(amount), dated, terms, dueBy, clean(note), corrects);
140	        added.refer(referred);
141	        List<String> tagged = Claim.tagsOf(tags);
142	        added.tag(tagged);
143	        // A claim dated by the sheet's entry date is meant to be dated there: it is late by the sheet's today.
144	        LocalDate entered = date != null ? date : sheet.getToday();
145	        if (periods.softClosedOn(sheetId, entered) || periods.softClosedOn(sheetId, dueBy)
146	                || periods.softClosedOn(sheetId, holidays.dueBy(sheetId, dated, terms(sheet, person, sheet.getToday())))) {
147	            added.markLateEntry();
148	        }
149	        Claim claim = claims.saveAndFlush(added);
150	        claim = logged(claim, user, person);
151	        audited("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
152	                (referred != null ? " ref=" + referred : "")
153	                        + (tagged.isEmpty() ? "" : " tags=" + String.join(",", tagged)));
154	        if (claim.isLateEntry()) {
