164	     * was added, and so its period. Refused when the claim's due-by, or the due-by a new date would give it
165	     * (the terms-th business day after it), is inside a closed period, or when it
166	     * would be a correction that does not name a SETTLED claim of the same person, or when its external
167	     * reference (null: kept as it is; blank: none) is already used by another claim on the sheet. Its tags
168	     * (null: kept as they are) are set from the comma separated text (see {@link Claim#tagsOf}).
169	     */
170	    @Transactional
171	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
172	            String corrects, String ref, String tags) {
173	        Rollups.Rollup before = rollups.take(sheetId);
174	        sheets.lock(sheetId);
175	        Claim claim = claim(sheetId, claimId);
176	        refuseUnlessEditable(sheetId, user, claim);
