298	    /**
299	     * Move a claim as {@link #move(String, String, long, ClaimStatus)} does, voiding it with a reason:
300	     * while the sheet's list of void reasons is not empty, a void needs one from it (see
301	     * {@link VoidReasonService#require}); the claim keeps it and its audit record ends with it.
302	     */
303	    @Transactional
304	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next, String reason) {
305	        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
306	        // sheet are serialised: each sees the other's committed claim and number.
307	        LocalDate today = sheets.lock(sheetId).getToday();
308	        Rollups.Rollup before = rollups.take(sheetId);
309	        Claim claim = claim(sheetId, claimId);
310	        periods.refuseIfClosed(sheetId, claim.getDueBy());
311	        String action = switch (next) {
312	            case OPEN -> "open";
313	            case SETTLED -> "settle";
314	            case VOID -> "void";
315	            case PENDING, DRAFT, DELETED -> throw new IllegalArgumentException("No move to " + next + ".");
316	        };
317	        if (!roles.permits(sheetId, user, action)) {
318	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
319	        }
320	        if (!claim.getStatus().canBecome(next)) {
321	            throw new ResponseStatusException(HttpStatus.CONFLICT,
322	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
323	        }
324	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
325	        if (voidingSettled) {
326	            refuseVoidingSettled(sheetId, user, claim, today);
327	        }
328	        String voidReason = next == ClaimStatus.VOID ? voidReasons.require(sheetId, reason) : null;
329	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
330	            throw new ResponseStatusException(HttpStatus.CONFLICT,
331	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
332	        }
333	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
334	            throw new ResponseStatusException(HttpStatus.CONFLICT,
335	                    "The user who opened or last edited a claim cannot settle it.");
336	        }
337	        Person person = person(sheetId, claim.getPersonId());
338	        BigDecimal settledDue = next == ClaimStatus.SETTLED
339	                ? dues.settling(claim, person.gradeOn(claim.getDate()))
340	                : null;
341	        if (next == ClaimStatus.OPEN) {
342	            periods.refuseIfCapped(sheetId, claim);
343	            refuseUnnoted(sheetId, claim, dues.due(claim, person.gradeOn(claim.getDate())));
344	        }
345	        if (next == ClaimStatus.SETTLED) {
346	            refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), settledDue);
347	        }
348	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settledDue)) {
349	            next = ClaimStatus.PENDING;
350	            settledDue = null;
351	        }
352	        claim.become(next);
353	        if (next == ClaimStatus.OPEN) {
354	            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
355	            claim.openedBy(user);
356	        }
357	        if (next == ClaimStatus.SETTLED) {
358	            claim.settleDue(settledDue);
359	        }
360	        if (next == ClaimStatus.VOID) {
361	            claim.voidedWith(voidReason);
362	        }
363	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
364	        String event = switch (next) {
365	            case OPEN -> "CLAIM_OPENED";
366	            case SETTLED -> "CLAIM_SETTLED";
367	            case PENDING -> "CLAIM_PENDING";
368	            case VOID -> "CLAIM_VOIDED";
369	            case DRAFT, DELETED -> throw new IllegalStateException();
370	        };
371	        String suffix = next == ClaimStatus.SETTLED
372	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
373	                : voidingSettled
374	                ? " reversed=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
375	                : "";
376	        if (voidReason != null) {
377	            suffix += " reason=" + voidReason;
378	        }
379	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
380	        if (next == ClaimStatus.SETTLED) {
381	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
382	        }
383	        rollups.audit(sheetId, user, before);
384	        return saved;
385	    }
