522	        sheets.lock(sheetId);
523	        Rollups.Rollup before = rollups.take(sheetId);
524	        Claim claim = pending(sheetId, user, claimId);
525	        if (claim.isOpenedOrEditedBy(user)) {
526	            throw new ResponseStatusException(HttpStatus.CONFLICT,
527	                    "The user who opened or last edited a claim cannot approve it.");
