542	    /**
543	     * Re-settle a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
544	     * claim bound by no statement (today's rates, grades, floor and late charge). Only a steward
545	     * re-settles; refused when the claim is not SETTLED or is due by inside a closed period.
546	     */
547	    @Transactional
548	    public Claim resettle(String sheetId, String user, long claimId) {
549	        sheets.lock(sheetId);
550	        Rollups.Rollup before = rollups.take(sheetId);
551	        Claim claim = claim(sheetId, claimId);
552	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
553	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
554	        }
555	        if (claim.getStatus() != ClaimStatus.SETTLED) {
556	            throw new ResponseStatusException(HttpStatus.CONFLICT,
557	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
558	        }
