560	        Person person = person(sheetId, claim.getPersonId());
561	        BigDecimal old = claim.getSettledDue();
562	        claim.settleDue(dues.resettling(claim, person.gradeOn(claim.getDate())));
563	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
564	        audited("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
565	                " old=" + (old != null ? old.toPlainString() : NO_RATE)
566	                        + " new=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
567	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
