602	    /**
603	     * Reassign a claim as {@link #reassign(String, String, long, long)} does; when {@code toOwn} is set,
604	     * a claim already the new person's is not refused but reassigned to them again (as a bulk
605	     * reassign does to each selected claim).
606	     */
607	    @Transactional
608	    public Claim reassign(String sheetId, String user, long claimId, long personId, boolean toOwn) {
609	        sheets.lock(sheetId);
610	        Rollups.Rollup before = rollups.take(sheetId);
611	        Claim claim = claim(sheetId, claimId);
612	        if (!roles.permits(sheetId, user, "reassign")) {
613	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim.");
614	        }
615	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
616	            throw new ResponseStatusException(HttpStatus.CONFLICT,
617	                    "A " + claim.getStatus() + " claim cannot be reassigned.");
618	        }
619	        periods.refuseIfClosed(sheetId, claim.getDueBy());
620	        Person from = person(sheetId, claim.getPersonId());
621	        Person to = person(sheetId, personId);
622	        if (!toOwn && from.getId().equals(to.getId())) {
623	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
624	        }
625	        refuseIfRetired(to, claim.getDate());
626	        refuseUnlessCorrects(sheetId, personId, claim.getAmount(), claim.getCorrects());
627	        claim.reassign(to.getId());
628	        claim.unbind();
629	        if (claim.getNumber() != null) {
630	            claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
631	        }
632	        Claim saved = claims.saveAndFlush(claim);
633	        audited("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
634	                " from=" + from.getName() + " to=" + to.getName());
635	        rollups.audit(sheetId, user, before);
636	        return saved;
637	    }
