672	    /**
673	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
674	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
675	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
676	     * from the terms in force on its date, names the original's number as the one it was split from;
677	     * it is a late entry when that due-by is inside a soft-closed period. Refused when the claim is not
678	     * OPEN, is deferred on the sheet's today, or when its due-by or the new claim's is inside a closed
679	     * period.
680	     */
681	    @Transactional
682	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
683	        Sheet sheet = sheets.lock(sheetId);
684	        LocalDate today = sheet.getToday();
685	        Rollups.Rollup before = rollups.take(sheetId);
686	        Claim claim = claim(sheetId, claimId);
687	        if (claim.getStatus() != ClaimStatus.OPEN) {
688	            throw new ResponseStatusException(HttpStatus.CONFLICT,
689	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
690	        }
691	        if (claim.isDeferredOn(today)) {
692	            throw new ResponseStatusException(HttpStatus.CONFLICT,
693	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
694	        }
695	        periods.refuseIfClosed(sheetId, claim.getDueBy());
696	        BigDecimal off = money(amount);
697	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
698	            throw new ResponseStatusException(HttpStatus.CONFLICT,
699	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
700	        }
701	        Person person = person(sheetId, claim.getPersonId());
702	        int terms = terms(sheet, person, claim.getDate());
703	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
704	        periods.refuseIfClosed(sheetId, dueBy);
705	        Claim split = claim.split(off, terms, dueBy);
706	        if (periods.softClosedOn(sheetId, dueBy)) {
707	            split.markLateEntry();
708	        }
709	        split.number(periods.nextClaimNumber(sheetId, split.getDueBy()));
710	        split.openedBy(user);
711	        Claim original = claims.saveAndFlush(claim);
712	        split = logged(claims.saveAndFlush(split), user, person);
713	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
714	        audited("CLAIM_OPENED", sheetId, user, person, split);
715	        rollups.audit(sheetId, user, before);
716	        return new Split(original, split);
717	    }
