736	    /**
737	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
738	     * on the claim's date: its person's grade's (the grade in force then) when one is set, else the
739	     * sheet's (a due of n/a is within any threshold).
740	     */
741	    private void refuseUnproved(String sheetId, Claim claim, String grade, BigDecimal due) {
742	        BigDecimal threshold = sheets.load(sheetId).proofThresholdFor(grade, claim.getDate());
743	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
744	            throw new ResponseStatusException(HttpStatus.CONFLICT,
745	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
746	                            + ": it needs a proof before it is settled.");
747	        }
748	    }
