751	     * Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
752	     * on the claim's date (a due of n/a is within any threshold).
753	     */
754	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
755	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
756	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
757	                && due.compareTo(threshold) > 0) {
758	            throw new ResponseStatusException(HttpStatus.CONFLICT,
759	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
760	                            + ": it needs a note before it is opened.");
761	        }
762	    }
