764	    /**
765	     * Refuse voiding a SETTLED claim unless the user acts as a steward and the sheet's today is no more
766	     * than {@link ClaimStatus#VOID_SETTLED_DAYS} days after the claim's settlement in its status log.
767	     */
768	    private void refuseVoidingSettled(String sheetId, String user, Claim claim, LocalDate today) {
769	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
770	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim.");
771	        }
772	        LocalDate settledOn = claim.settledOn();
773	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
774	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can only be voided within "
775	                    + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
776	        }
777	    }
