779	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit. */
780	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
781	        BigDecimal limit = sheets.clerkLimit(sheetId);
782	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
783	            return false;
784	        }
785	        return Role.CLERK.equals(roles.roleOf(sheetId, user));
786	    }
787	
788	    /**
789	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
790	     * same person; and refuse naming a claim to correct on any other claim.
791	     */
792	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
793	        if (amount.signum() >= 0) {
794	            if (corrects != null) {
795	                throw new ResponseStatusException(HttpStatus.CONFLICT,
796	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
797	            }
798	            return;
799	        }
800	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
801	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
802	                .isPresent();
803	        if (!settled) {
804	            throw new ResponseStatusException(HttpStatus.CONFLICT,
805	                    "A correction must name the number of a SETTLED claim of the same person.");
806	        }
807	    }
808	
809	    /** Refuse a claim dated after its person's retirement, or after the from and before the to of a past one. */
810	    private static void refuseIfRetired(Person person, LocalDate date) {
811	        if (!person.canClaimOn(date)) {
812	            throw new ResponseStatusException(HttpStatus.CONFLICT,
813	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
814	        }
815	        Retirement past = person.pastRetirementBarring(date);
816	        if (past != null) {
817	            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " was retired from "
818	                    + past.getFromDate() + " to " + past.getToDate() + ": a claim cannot be dated within it.");
819	        }
820	    }
821	
822	    private Claim claim(String sheetId, long claimId) {
823	        return claims.findByIdAndSheetId(claimId, sheetId)
824	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
825	    }
826	
827	    /**
828	     * The terms, in business days, a claim of the person dated on a date is fixed with: the first of the
829	     * person's own terms, their grade's terms and the sheet's terms in force on it.
830	     */
831	    private static int terms(Sheet sheet, Person person, LocalDate date) {
832	        Integer own = person.getTerms();
833	        return own != null ? own : sheet.termsFor(person.gradeOn(date), date);
834	    }
835	
836	    private Person person(String sheetId, long personId) {
837	        return people.findByIdAndSheetId(personId, sheetId)
838	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
839	    }
840	
841	    /**
842	     * Add a line to the claim's status log for the status it now has: by the user, on the sheet's
843	     * today, with its due as computed now.
844	     */
845	    private Claim logged(Claim claim, String user, Person person) {
846	        claim.logged(user, sheets.today(claim.getSheetId()), dues.due(claim, person.gradeOn(claim.getDate())));
847	        return claims.saveAndFlush(claim);
848	    }
849	
850	    /** Record the change to the claim once it is committed; a claim with a number carries it. */
851	    private void audited(String event, String sheetId, String user, Person person, Claim claim) {
852	        audited(event, sheetId, user, person, claim, claim.getNumber(), "");
853	    }
854	
855	    private void audited(String event, String sheetId, String user, Person person, Claim claim, String number,
856	            String suffix) {
857	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
858	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
859	                + (number != null ? " number=" + number : "") + suffix);
860	    }
861	
862	    /** The due figure a claim shows, without its late charge (see {@link Dues#figure}). */
863	    public BigDecimal figure(Claim claim, String grade) {
864	        return dues.figure(claim, grade);
865	    }
866	
867	    /** The due a claim shows, with its late charge (see {@link Dues#due}). */
868	    public BigDecimal due(Claim claim, String grade) {
869	        return dues.due(claim, grade);
870	    }
871	
872	    /** Refuse a reference already used on the sheet by a claim other than the one given (null: any). */
873	    private void refuseIfReferred(String sheetId, String ref, Long self) {
874	        if (ref == null) {
875	            return;
876	        }
877	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
878	                .filter((other) -> !other.getId().equals(self))
879	                .ifPresent((other) -> {
880	                    throw new ResponseStatusException(HttpStatus.CONFLICT,
881	                            "The reference " + ref + " is already used on this sheet.");
882	                });
883	    }
884	
885	    /** A reference as typed, without surrounding spaces; null when blank. */
886	    static String reference(String ref) {
887	        return ref == null || ref.isBlank() ? null : ref.trim();
888	    }
889	
890	    private static BigDecimal money(BigDecimal amount) {
891	        return amount.setScale(2, RoundingMode.UNNECESSARY);
892	    }
893	
894	    private static String clean(String note) {
895	        return note == null ? "" : note.trim();
896	    }
897	}
